import{c as e,Q as a,j as o,m as i}from"./chunks/framework.COywXlYp.js";const g=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{"layout":"doc","title":"Getting Started"},"headers":[],"relativePath":"en/guide/getting-started.md","filePath":"en/guide/getting-started.md"}'),n={name:"en/guide/getting-started.md"};function c(r,t,l,s,u,d){return a(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><h2 id="download-and-install" tabindex="-1">Download and Install <a class="header-anchor" href="#download-and-install" aria-label="Permalink to &quot;Download and Install&quot;">​</a></h2><p>Go to <a href="https://github.com/xystudiocode/pyClickMouse/releases/latest" target="_blank" rel="noreferrer">GitHub releases page</a></p><p>Select <code>clickmouse.7z</code>, then download, after downloading, extract to current directory</p><h2 id="running" tabindex="-1">Running <a class="header-anchor" href="#running" aria-label="Permalink to &quot;Running&quot;">​</a></h2><h3 id="initialization" tabindex="-1">Initialization <a class="header-anchor" href="#initialization" aria-label="Permalink to &quot;Initialization&quot;">​</a></h3><p>Click <code>extracted folder/main.exe</code>, agree to UAC popup, wait for program initialization to complete.</p><p>First click Next, then &quot;Agree to this agreement&quot;, click &quot;Next&quot; 2 times <img class="license" alt="License agreement"></p><p>Then you will be asked whether to create a shortcut, recommended to create, click &quot;Next&quot;</p><img class="shortcut" alt="Create shortcut"><p>Then select packages, you can choose as appropriate, click &quot;Next&quot;, confirm component selection popup.</p><img class="compoments" alt="Component selection"><p>Then wait for installation to complete, enter installation completion prompt page, recommended to check &quot;Run clickmouse&quot;, click &quot;Finish&quot;</p><img class="finish" alt="Installation complete"><h3 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h3><p>Set a click interval and click count, the button next to the click input box can set the unit</p><p>After setting, click &quot;Left Click&quot; or &quot;Right Click&quot; button to start clicking</p><blockquote><p>If grayed out, check if numbers are entered, clickmouse only detects integer numbers</p></blockquote><p>Click &quot;Stop&quot; button to stop clicking</p><p>Click &quot;Pause&quot; button can pause clicking, then you can click &quot;Restart&quot; button to continue clicking</p><img class="clickmouse" alt="clickmouse running interface"><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>Afterwards, to run, you can double-click <code>extracted folder/main.exe</code> to run the program, or right-click desktop or start menu shortcut to run</p></div>',22)])])}const h=e(n,[["render",c]]);export{g as __pageData,h as default};
